async function main() {
  const devUsers = await db
    .select({ id: users.id, name: users.name })
    .from(users)
    .where(inArray(users.email, DEV_EMAILS));

  if (devUsers.length === 0) throw new Error("No dev users. Run seed:dev first.");
  console.log(`Found ${devUsers.length} dev users. Adding top-up posts...`);

  const extras: PostSeed[] = [
    ...EXTRA_BEHANCE,
    ...EXTRA_PINTEREST,
    ...EXTRA_DRIBBBLE,
    ...EXTRA_UNSPLASH,
    ...EXTRA_MEDIUM,
  ];

  let inserted = 0;
  for (let i = 0; i < extras.length; i++) {
    const seed = extras[i]!;
    const author = devUsers[i % devUsers.length]!;
    const now = new Date(Date.now() - i * 60_000);
    const result = await db.insert(posts).values({
      userId: author.id,
      title: seed.title,
      link: seed.link,
      body: seed.body,
      thumbnailUrl: seed.thumbnailUrl,
      profileThumbnailUrl: seed.profileThumbnailUrl,
      providerName: seed.providerName,
      tags: randomTags(),
      createdAt: now,
      updatedAt: now,
    }).onConflictDoNothing({ target: posts.link }).returning({ id: posts.id });

    if (result.length > 0) {
      const postId = result[0]!.id;
      const commenter = devUsers[(i * 3 + 2) % devUsers.length]!;
      await db.insert(comments).values({
        postId, userId: commenter.id,
        body: "Excellent find. Added to my reference collection immediately.",
        parentId: null, replyToUserName: null,
      });
      await db.execute(sql`UPDATE ${posts} SET comments_count = comments_count + 1 WHERE id = ${postId}`);
      inserted++;
    }
  }

  console.log(`Top-up complete: ${inserted} posts added.`);
}

main()
  .catch((err) => { console.error(err); process.exit(1); })
  .finally(() => client.end());
